def render_response_from_env(env):
    # الحصول على معلمة الاسم من الطلب
    name = env.get('QUERY_STRING', '').split('name=')[-1].split('&')[0] if 'name=' in env.get('QUERY_STRING', '') else None

    # الحصول على القالب من البيئة
    template = env.get('TEMPLATE', '')

    # إذا كانت هناك معلمة اسم، نعرض القالب مع الاسم
    if name:
        response_body = template.format(name=name)
    else:
        # إذا لم تكن هناك معلمة اسم، نُرجع استجابة فارغة
        response_body = ''

    # إرجاع الاستجابة مع القالب المقدم
    return {
        'status': '200 OK',
        'headers': [('Content-Type', 'text/html')],
        'body': response_body
    }

def home(env):
    # استدعاء الدالة render_response_from_env باستخدام المتغير env
    return render_response_from_env(env)

# الدالة الرئيسية التي تُرجع الاستجابة من render_response_from_env
def main(env, start_response):
    response = home(env)
    start_response(response['status'], response['headers'])
    return [response['body'].encode('utf-8')]

