from flask import Flask, request, render_template_string, jsonify

app = Flask(__name__)

def render_response_from_env(env):
    # Get the 'name' parameter from the request
    name = request.args.get('name')

    # Check if 'name' parameter is present
    if not name:
        return jsonify({"error": "Name parameter is required"}), 400

    # Get the template from the environment
    template = env.get('template')

    # Check if template exists
    if not template:
        return jsonify({"error": "Template not found in environment"}), 404

    # Render the template with the name parameter
    try:
        rendered_template = render_template_string(template, name=name)
        return rendered_template
    except Exception as e:
        return jsonify({"error": "Template rendering failed", "details": str(e)}), 500

@app.route('/')
def home():
    # Example environment with a template
    env = {
        'template': '<h1>Hello, {{ name }}!</h1>'
    }

    # Call render_response_from_env with the environment
    return render_response_from_env(env)

if __name__ == '__main__':
    app.run(debug=True)

